svg.script:
//
    function a16p5SelectTab(tabId) {
      // 1. Hide all panels
      var panels = document.querySelectorAll('.a16p5-panel');
      for (var i = 0; i < panels.length; i++) {
        panels[i].classList.remove('a16p5-visible');
      }

      // 2. Deactivate all buttons
      var buttons = document.querySelectorAll('.a16p5-tab-btn');
      for (var j = 0; j < buttons.length; j++) {
        buttons[j].classList.remove('a16p5-active');
        buttons[j].setAttribute('aria-selected', 'false');
      }

      // 3. Show targeted panel
      var targetPanel = document.getElementById('a16p5-panel-' + tabId);
      if (targetPanel) {
        targetPanel.classList.add('a16p5-visible');
      }

      // 4. Activate targeted button
      var targetBtn = document.getElementById('a16p5-btn-' + tabId);
      if (targetBtn) {
        targetBtn.classList.add('a16p5-active');
        targetBtn.setAttribute('aria-selected', 'true');
      }
    }
  //
